// ─── Plan Generation Tasks ──────────────────────────────────
// Fetches all data, plans what to generate for today

const clients = $('Get Active Clients').all().map(i => i.json);
const allSlots = $('Get All Slot Settings').all().map(i => i.json);
const campaigns = $('Get Active Campaigns').all().map(i => i.json);

const now = new Date();
const todayDow = now.getDay(); // 0=Sun, 1=Mon, ..., 6=Sat
const todayStr = now.toISOString().split('T')[0]; // YYYY-MM-DD
const tz = 'Europe/Zurich';

const tasks = [];

for (const client of clients) {
  const customerId = client.Customer_ID;

  // Get today's slots for this client
  const clientSlots = allSlots.filter(s => 
    s.Customer_ID === customerId && 
    (s.Day_of_Week === todayDow || s.dayOfWeek === todayDow)
  );

  if (clientSlots.length === 0) continue;

  // Check for active campaigns for this client
  const clientCampaigns = campaigns.filter(c => {
    // Campaign may link to customer by name or ID
    const campCustomer = Array.isArray(c.Customer_Name) ? c.Customer_Name : [c.Customer_Name];
    return campCustomer.some(cn => cn === client.Customer_Name || cn === customerId);
  });

  // Sort slots by time
  clientSlots.sort((a, b) => (a.Time || '00:00').localeCompare(b.Time || '00:00'));

  for (let i = 0; i < clientSlots.length; i++) {
    const slot = clientSlots[i];
    const slotTime = slot.Time || '12:00';
    const slotDateTime = `${todayStr}T${slotTime}:00+01:00`;

    // Determine format: alternate image/video
    // Pattern: image, image, video, image, video (for 5 slots)
    // For fewer slots: mostly images, last one video
    const isVideoSlot = (clientSlots.length <= 2) 
      ? (i === clientSlots.length - 1) // last slot = video
      : (i % 3 === 2); // every 3rd slot = video

    const format = isVideoSlot ? 'video' : 'image';
    const platform = slot.Platform || (isVideoSlot ? 'TikTok' : 'Instagram');

    // Check if campaign should fill this slot
    let source = 'Rotation';
    let campaignId = '';
    let brief = '';
    let productName = '';

    if (clientCampaigns.length > 0) {
      // Campaign slots take priority (fill first N slots with campaign content)
      const campaign = clientCampaigns[0]; // Highest priority campaign
      const remaining = (campaign.Posts_Needed || 0) - (campaign.Posts_Generated || 0);

      if (remaining > 0) {
        source = campaign.Source || 'Planifiée';
        campaignId = campaign.Campaign_Title || '';
        brief = campaign.Brief || campaign.Objectives || '';
        // Don't specify product — let rotation handle it even for campaigns
      }
    }

    tasks.push({
      json: {
        customer_id: customerId,
        customer_name: client.Customer_Name,
        platform: platform,
        format: format,
        source: source,
        campaign_id: campaignId,
        product_name: productName,
        brief: brief,
        slot_time: slotDateTime,
        slot_index: i,
        total_slots: clientSlots.length
      }
    });
  }
}

if (tasks.length === 0) {
  // No tasks for today — return empty to stop the workflow
  return [{ json: { _no_tasks: true, message: `No slots for day ${todayDow}` } }];
}

return tasks;

